insert into public.paginas (id, contenido) values ('blog', '{"seo":{"foto":"cafe.jpg","titulo":{"en":"Colombia travel blog · Wanna Go","es":"Blog de viajes por Colombia · Wanna Go"},"descripcion":"Historias, consejos y destinos para viajar por Colombia con propósito, escritos desde Medellín por el equipo de Wanna Go."},"cierre":{"foto":"guatape.jpg","titulo":{"en":"Feeling inspired? Let''s design your trip","es":"¿Te inspiraste? Diseñemos tu viaje"},"whatsapp":"Hola Wanna Go, leí su blog y quiero diseñar un viaje."},"listado":{"ceja":{"en":"Posts","es":"Entradas"},"vacio":{"en":"Coming soon: stories and tips for your next trip.","es":"Muy pronto publicaremos aquí historias y consejos para tu próximo viaje."},"titulo":{"en":"Latest from the blog","es":"Lo último del blog"}},"portada":{"alt":{"en":"Ripe coffee cherries on the branch","es":"Granos de café maduros en la rama"},"foto":"cafe.jpg","texto":{"en":"Destinations, tips and stories from Colombia and the world, told by the people who travel them.","es":"Destinos, consejos y relatos de Colombia y del mundo, contados por quienes los recorren."},"titulo":{"en":"Stories for purposeful travel","es":"Historias para viajar con propósito"},"etiqueta":{"en":"Blog","es":"Blog"}}}'::jsonb) on conflict (id) do update set contenido = excluded.contenido;
insert into public.paginas (id, contenido) values ('contacto', '{"seo":{"foto":"medellin.jpg","titulo":{"en":"Contact · Wanna Go Colombia, Medellín","es":"Contacto · Wanna Go Colombia, Medellín"},"descripcion":"Escríbenos por WhatsApp al +57 312 289 9185 o a wannagoco@gmail.com. Oficina en El Poblado, Medellín. Diseñamos tu viaje por Colombia."},"canales":{"ceja":{"en":"Channels","es":"Canales"},"texto":{"en":"Tell us what moves you and we''ll propose an itinerary made for you. We reply on WhatsApp.","es":"Cuéntanos qué te mueve y te proponemos un itinerario a tu medida. Respondemos por WhatsApp."},"titulo":{"en":"Let''s talk about your trip","es":"Hablemos de tu viaje"}},"portada":{"alt":{"en":"Medellín lit up at dusk, surrounded by mountains","es":"Medellín iluminada al atardecer, rodeada de montañas"},"foto":"medellin.jpg","texto":{"en":"Tell us what moves you and we''ll propose an itinerary made for you. We reply on WhatsApp.","es":"Cuéntanos qué te mueve y te proponemos un itinerario a tu medida. Respondemos por WhatsApp."},"titulo":{"en":"Let''s plan your next trip","es":"Diseñemos tu próximo viaje"},"etiqueta":{"en":"Contact","es":"Contacto"}}}'::jsonb) on conflict (id) do update set contenido = excluded.contenido;
insert into public.paginas (id, contenido) values ('destinos', '{"seo":{"foto":"guatape.jpg","titulo":{"en":"Destinations in Colombia for purposeful travel · Wanna Go","es":"Destinos en Colombia para viajar con propósito · Wanna Go"},"descripcion":"Guatapé, Comuna 13, Cartagena, Valle de Cocora, Tayrona y el Eje Cafetero: viajes por Colombia diseñados desde Medellín por Wanna Go."},"cierre":{"foto":"medellin.jpg","titulo":{"en":"Can''t decide? We''ll help","es":"¿No sabes cuál elegir? Te ayudamos"},"whatsapp":"Hola Wanna Go, quiero ideas para viajar por Colombia."},"listado":{"ceja":{"en":"Destinations","es":"Destinos"},"titulo":{"en":"Choose where to start","es":"Elige por dónde empezar"}},"portada":{"alt":{"en":"Guatapé reservoir and its green islands seen from above","es":"Embalse de Guatapé con sus islas verdes visto desde lo alto"},"foto":"guatape.jpg","texto":{"en":"Places we design with care, from Medellín to the Caribbean. Each one can be combined into a tailor-made trip.","es":"Lugares que diseñamos con cariño, desde Medellín hasta el Caribe. Cada uno se puede combinar en un viaje a tu medida."},"titulo":{"en":"Discover Colombia from the inside","es":"Conoce Colombia desde adentro"},"etiqueta":{"en":"Destinations in Colombia","es":"Destinos en Colombia"}}}'::jsonb) on conflict (id) do update set contenido = excluded.contenido;
insert into public.paginas (id, contenido) values ('eventos-corporativos', '{"seo":{"foto":"medellin-montanas.jpg","titulo":{"en":"Corporate events in Medellín and Antioquia · Wanna Go","es":"Eventos corporativos en Medellín y Antioquia · Wanna Go"},"descripcion":"Incentivos, convenciones y experiencias de equipo en Medellín y Antioquia, con logística completa y experiencias locales con propósito."},"intro":{"alt":{"en":"Medellín lit up at dusk, surrounded by mountains","es":"Medellín iluminada al atardecer, rodeada de montañas"},"ceja":{"en":"01 · For companies","es":"01 · Para empresas"},"foto":"medellin.jpg","titulo":{"en":"Experiences that bring teams together","es":"Experiencias que unen equipos"},"parrafos":[{"en":"We design incentive trips, conventions and team outings that show Medellín and Antioquia from the inside, with the same warmth we offer every traveler.","es":"Diseñamos viajes de incentivo, convenciones y salidas de equipo que muestran Medellín y Antioquia desde adentro, con la misma calidez con la que recibimos a nuestros viajeros."},{"en":"We handle the full logistics: transport, lodging, venues, catering and local experiences, with a single point of contact.","es":"Nos encargamos de la logística completa: transporte, alojamiento, espacios, alimentación y experiencias locales, con un solo contacto para todo."}]},"pasos":{"ceja":{"en":"02 · What we organize","es":"02 · Qué organizamos"},"items":[{"texto":{"en":"Reward your team with experiences they won''t forget.","es":"Premia a tu equipo con experiencias que no olvidará."},"titulo":{"en":"Incentive trips","es":"Viajes de incentivo"}},{"texto":{"en":"Venues, transport and agenda, all coordinated.","es":"Espacios, transporte y agenda coordinados."},"titulo":{"en":"Conventions and meetings","es":"Convenciones y reuniones"}},{"texto":{"en":"Purposeful activities in the city and in nature.","es":"Actividades con propósito en la ciudad y la naturaleza."},"titulo":{"en":"Team building","es":"Integración de equipos"}},{"texto":{"en":"Welcome clients and partners with the best of Medellín.","es":"Recibe a clientes y socios con lo mejor de Medellín."},"titulo":{"en":"Experiences for visitors","es":"Experiencias para visitantes"}}],"titulo":{"en":"Formats for your company","es":"Formatos para tu empresa"}},"cierre":{"foto":"medellin-montanas.jpg","titulo":{"en":"Tell us about your event","es":"Cuéntanos de tu evento"},"whatsapp":"Hola Wanna Go, quiero cotizar un evento corporativo."},"portada":{"alt":{"en":"Medellín buildings against the mountains","es":"Edificios de Medellín frente a las montañas"},"foto":"medellin-montanas.jpg","texto":{"en":"Incentive trips, conventions and team experiences with full logistics in Medellín and Antioquia.","es":"Incentivos, convenciones y experiencias de equipo con logística completa en Medellín y Antioquia."},"titulo":{"en":"Corporate events in Medellín and Antioquia","es":"Eventos corporativos en Medellín y Antioquia"},"etiqueta":{"en":"Companies","es":"Empresas"},"whatsapp":"Hola Wanna Go, quiero cotizar un evento corporativo."},"resenas":{"ceja":{"en":"What people say","es":"Lo que dicen"},"titulo":{"en":"Stories from people who traveled with us","es":"Historias de quienes viajaron con nosotros"}},"destinos":{"ceja":{"en":"03 · Experiences","es":"03 · Experiencias"},"lista":["comuna-13","guatape","plazas-de-mercado"],"titulo":{"en":"Ideas in Medellín and Antioquia","es":"Ideas en Medellín y Antioquia"}}}'::jsonb) on conflict (id) do update set contenido = excluded.contenido;
insert into public.paginas (id, contenido) values ('gracias', '{"seo":{"titulo":{"es":"Gracias · Wanna Go","en":"Thank you · Wanna Go"},"descripcion":"Recibimos tu mensaje. Te respondemos por WhatsApp lo más rápido posible.","foto":"grupo-atardecer.jpg"},"portada":{"foto":"grupo-atardecer.jpg","alt":{"es":"Grupo de viajeras al atardecer","en":"Group of travelers at sunset"},"etiqueta":{"es":"¡Gracias!","en":"Thank you!"},"titulo":{"es":"Ya casi nos vamos","en":"We''re almost on our way"},"texto":{"es":"Te abrimos WhatsApp con tu mensaje listo. Solo dale enviar y te respondemos lo más rápido posible.","en":"We opened WhatsApp with your message ready. Just hit send and we''ll reply as soon as possible."},"boton":{"es":"¿No se abrió? Escríbenos aquí","en":"Didn''t open? Message us here"}}}'::jsonb) on conflict (id) do update set contenido = excluded.contenido;
insert into public.paginas (id, contenido) values ('inicio', '{"seo":{"foto":"medellin.jpg","titulo":{"en":"Wanna Go Colombia · Purposeful travel agency in Medellín","es":"Wanna Go Colombia · Agencia de viajes con propósito en Medellín"},"descripcion":"Wanna Go: agencia de turismo receptivo en Medellín. Viajes a la medida, viajes grupales y eventos corporativos con propósito."},"frase":{"foto":"guatape.jpg","firma":"Wanna Go Colombia","texto":{"en":"“Travel with purpose, come home with stories.”","es":"“Viajar con propósito, volver con historias.”"}},"viajes":{"ceja":{"en":"01 · Our trips","es":"01 · Nuestros viajes"},"titulo":{"en":"Choose your next trip","es":"Elige tu próximo viaje"},"cta_boton":{"en":"Get started","es":"Empezar"},"cta_titulo":{"en":"Design your own trip","es":"Diseña tu propio viaje"},"cta_etiqueta":{"en":"At your pace","es":"A tu ritmo"}},"pilares":{"ceja":{"en":"04 · Our signature","es":"04 · Nuestro sello"},"items":[{"texto":{"en":"We support local businesses, respect the culture and protect the natural environment.","es":"Fomentamos el comercio local, respetamos la cultura y protegemos el entorno natural."},"titulo":{"en":"Local impact and sustainability","es":"Impacto local y sostenibilidad"}},{"texto":{"en":"We create space to learn, reconnect, pause and grow.","es":"Creamos espacios para aprender, reconectar, hacer una pausa y crecer."},"titulo":{"en":"Personal transformation","es":"Transformación personal"}},{"texto":{"en":"Genuine experiences, far from rushed mass tourism.","es":"Experiencias genuinas, lejos del turismo masivo y acelerado."},"titulo":{"en":"Authenticity and exclusivity","es":"Autenticidad y exclusividad"}},{"texto":{"en":"A personal touch of care and detail at every point of the trip.","es":"Un sello personal de cuidado y detalle en cada punto del viaje."},"titulo":{"en":"Warm hospitality","es":"Hospitalidad cálida"}}],"titulo":{"en":"The pillars of purposeful travel","es":"Pilares de los viajes con propósito"}},"portada":{"alt":{"en":"Medellín lit up at dusk, surrounded by mountains","es":"Medellín iluminada al atardecer, rodeada de montañas"},"foto":"medellin.jpg","texto":{"en":"We design tailor-made trips, group trips and corporate events with one clear signature: purposeful travel, where the destination transforms you and the company makes every trip memorable.","es":"Diseñamos viajes a la medida, viajes grupales y eventos corporativos con un sello claro: viajes con propósito, donde el destino transforma y la compañía hace que cada viaje sea memorable."},"boton1":{"en":"See upcoming trips","es":"Ver próximos viajes"},"boton2":{"en":"Plan my trip","es":"Diseñar mi viaje"},"titulo":{"en":"Colombia is best experienced in good company","es":"Colombia se vive mejor en buena compañía"},"etiqueta":{"en":"Inbound travel agency · Medellín","es":"Agencia de turismo receptivo · Medellín"}},"resenas":{"ceja":{"en":"05 · What people say","es":"05 · Lo que dicen"},"titulo":{"en":"Stories from people who traveled with us","es":"Historias de quienes viajaron con nosotros"}},"contacto":{"ceja":{"en":"07 · Contact","es":"07 · Contacto"},"texto":{"en":"Tell us what moves you and we''ll propose an itinerary made for you. We reply on WhatsApp.","es":"Cuéntanos qué te mueve y te proponemos un itinerario a tu medida. Respondemos por WhatsApp."},"titulo":{"en":"Let''s plan your next trip","es":"Diseñemos tu próximo viaje"}},"nosotros":{"alt":{"en":"Street with colorful facades and zócalos in Guatapé","es":"Calle con fachadas de colores y zócalos en Guatapé"},"ceja":{"en":"02 · Who we are","es":"02 · Quiénes somos"},"foto":"guatape-calle.jpg","cifras":[{"texto":{"en":"Year founded","es":"Año de fundación"},"valor":"2019"},{"texto":{"en":"National Tourism Registry","es":"Registro Nacional de Turismo"},"valor":"RNT 65568"},{"texto":{"en":"Colombia","es":"Colombia"},"valor":"Medellín"}],"enlace":{"en":"Learn more","es":"Conocer más"},"titulo":{"en":"Purposeful travel","es":"Viajes con propósito"},"parrafos":[{"en":"Wanna Go is an inbound travel agency based in Medellín, founded in 2019 by María Lucía Vásquez Cock, Luchy.","es":"Wanna Go es una agencia de turismo receptivo con sede en Medellín, fundada en 2019 por María Lucía Vásquez Cock, Luchy."},{"en":"We steer clear of mass tourism and the predictable. We show you each destination from the inside, through its people, its food and its landscapes, so you come home different from how you left.","es":"Huimos del turismo masivo y de lo predecible. Te mostramos cada destino desde adentro, con su gente, su cocina y sus paisajes, para que vuelvas distinto de como te fuiste."}]},"fundadora":{"foto":"luchy.jpg","alt":{"es":"María Lucía Vásquez Cock, Luchy, fundadora de Wanna Go, en Cartagena","en":"María Lucía Vásquez Cock, Luchy, founder of Wanna Go, in Cartagena"},"ceja":{"en":"06 · Founder","es":"06 · Fundadora"},"cita":{"en":"“I believe in trips that transform you: the ones that seat you at a local family''s table and send you home with stories.”","es":"“Creo en los viajes que transforman: los que te sientan a la mesa de una familia local y te devuelven a casa con historias.”"},"cargo":{"en":"Founder and experience designer","es":"Fundadora y diseñadora de experiencias"},"nombre":"María Lucía Vásquez Cock · Luchy"},"experiencias":{"ceja":{"en":"03 · What we do","es":"03 · Lo que hacemos"},"boton":{"en":"Learn more","es":"Conocer más"},"titulo":{"en":"Three ways to travel with us","es":"Tres formas de viajar con nosotros"},"tarjetas":[{"alt":{"en":"Wax palms in the Cocora Valley","es":"Palmas de cera en el valle de Cocora"},"foto":"salento.jpg","texto":{"en":"Private itineraries designed around what moves you: coffee, nature, food, art or rest.","es":"Itinerarios privados diseñados alrededor de lo que te mueve: café, naturaleza, cocina, arte o descanso."},"enlace":"viajes-a-la-medida/","titulo":{"en":"Tailor-made trips","es":"Viajes a la medida"},"etiqueta":{"en":"At your pace","es":"A tu ritmo"}},{"alt":{"en":"Group of travelers watching the sunset","es":"Grupo de viajeros contemplando el atardecer"},"foto":"grupo-atardecer.jpg","texto":{"en":"Hosted departures in Colombia and around the world, with a Wanna Go host from start to finish.","es":"Salidas acompañadas en Colombia y el mundo, con anfitriona Wanna Go de principio a fin."},"enlace":"viajes-grupales/","titulo":{"en":"Group trips","es":"Viajes grupales"},"etiqueta":{"en":"Small groups","es":"Grupos pequeños"}},{"alt":{"en":"Medellín buildings against the mountains","es":"Edificios de Medellín frente a las montañas"},"foto":"medellin-montanas.jpg","texto":{"en":"Incentive trips, conventions and team experiences with full logistics in Medellín and Antioquia.","es":"Incentivos, convenciones y experiencias de equipo con logística completa en Medellín y Antioquia."},"enlace":"eventos-corporativos/","titulo":{"en":"Corporate events","es":"Eventos corporativos"},"etiqueta":{"en":"Companies","es":"Empresas"}}]}}'::jsonb) on conflict (id) do update set contenido = excluded.contenido;
insert into public.paginas (id, contenido) values ('marruecos', '{"seo":{"foto":"mujer-dunas.jpg","titulo":{"en":"Morocco among women · Wanna Go","es":"Marruecos entre mujeres · Wanna Go"},"indexar":false,"descripcion":"Viaje solo para mujeres a Marruecos: 10 días, 7 destinos y máximo 16 viajeras, con anfitriona de Wanna Go. Medinas, palacios y una noche en el Sahara."},"aviso":{"texto":{"en":"DRAFT · Prices and dates marked {to be confirmed} will be completed with Wanna Go · Reference photos: Unsplash","es":"BORRADOR · Precios y fechas marcados como {por definir} se completan con Wanna Go · Fotos de referencia: Unsplash"},"activo":true},"noche":{"alt":{"en":"Desert tent camp lit up under the starry Sahara sky","es":"Campamento de jaimas iluminado bajo el cielo estrellado del Sahara"},"ceja":{"en":"The highlight of the trip","es":"El momento del viaje"},"foto":"jaima.jpg","texto":{"en":"A campfire, mint tea, Berber drums and more stars than you''ve ever seen.","es":"Fogata, té de menta, tambores bereberes y un cielo con más estrellas de las que has visto en tu vida."},"titulo":{"en":"A night *in the Sahara*","es":"Una noche *en el Sahara*"}},"viaje":{"alt1":{"en":"Blue courtyard with plants in Chefchaouen","es":"Patio azul con plantas en Chefchaouen"},"alt2":{"en":"Moroccan lanterns glowing in a souk","es":"Faroles marroquíes iluminados en un zoco"},"ceja":{"en":"The trip","es":"El viaje"},"foto1":"patio-azul.jpg","foto2":"faroles.jpg","titulo":{"en":"A trip you''ll remember *for a lifetime*, with women who experience it just like you","es":"Un viaje que se recuerda *toda la vida*, con mujeres que lo viven igual que tú"},"pilares":[{"texto":{"en":"Certified local guides, private transfers and a host with you around the clock.","es":"Guías locales certificadas, traslados privados y anfitriona contigo las 24 horas."},"titulo":{"en":"Safe","es":"Segura"}},{"texto":{"en":"16 travelers max. Arrive on your own, leave with friends.","es":"Máximo 16 viajeras. Llegas sola y te vas con amigas."},"titulo":{"en":"Intimate","es":"Íntima"}},{"texto":{"en":"Traditional hammam, cooking with a local family and a night at a desert camp.","es":"Hammam tradicional, cocina con una familia local y noche en campamento del desierto."},"titulo":{"en":"Authentic","es":"Auténtica"}},{"texto":{"en":"Hotels, transport, tickets and key meals already booked.","es":"Hoteles, transporte, entradas y comidas clave ya reservados."},"titulo":{"en":"No logistics","es":"Sin logística"}}]},"precio":{"alt":{"en":"Blue stairs in Chefchaouen","es":"Escaleras azules en Chefchaouen"},"ceja":{"en":"Price","es":"Inversión"},"foto":"chefchaouen-escaleras.jpg","nota":{"en":"From, per person in a double room","es":"Desde, por persona en habitación doble"},"boton":{"en":"Hold my spot","es":"Apartar mi cupo"},"filas":[{"valor":{"en":"{USD 000}","es":"{USD 000}"},"etiqueta":{"en":"Deposit to book","es":"Anticipo para reservar"}},{"valor":{"en":"{USD 000}","es":"{USD 000}"},"etiqueta":{"en":"Single room supplement","es":"Suplemento habitación individual"}},{"valor":{"en":"{dd / mm / 2027}","es":"{dd / mm / 2027}"},"etiqueta":{"en":"Departure date","es":"Fecha de salida"}},{"valor":{"en":"In installments before the trip","es":"En cuotas antes del viaje"},"etiqueta":{"en":"Balance","es":"Saldo"}}],"valor":{"en":"USD {0.000}","es":"USD {0.000}"},"titulo":{"en":"Your place in *the group*","es":"Tu lugar en *el grupo*"},"cupos_total":16,"mostrar_cupos":true,"cupos_etiqueta":{"en":"Spots booked {example}","es":"Cupos reservados {ejemplo}"},"cupos_reservados":9},"galeria":{"fotos":[{"foto":"chefchaouen-escaleras.jpg","nombre":{"en":"Chefchaouen","es":"Chefchaouen"}},{"foto":"camellos.jpg","nombre":{"en":"Erg Chebbi","es":"Erg Chebbi"}},{"foto":"majorelle.jpg","nombre":{"en":"Majorelle Garden","es":"Jardín Majorelle"}},{"foto":"especias.jpg","nombre":{"en":"The souk","es":"El zoco"}},{"foto":"kasbah.jpg","nombre":{"en":"Dades Valley","es":"Valle del Dades"}},{"foto":"fez.jpg","nombre":{"en":"Fez","es":"Fez"}},{"foto":"jaima.jpg","nombre":{"en":"Night in a desert tent","es":"Noche en jaima"}}]},"incluye":{"no":[{"en":"International flights {quote from MDE / BOG}","es":"Tiquetes internacionales {cotizar desde MDE / BOG}"},{"en":"Travel insurance (required)","es":"Seguro de viaje (obligatorio)"},{"en":"Lunches and drinks not listed","es":"Almuerzos y bebidas no mencionadas"},{"en":"Tips for guides and drivers","es":"Propinas a guías y conductores"},{"en":"Personal expenses","es":"Gastos personales"}],"si":[{"en":"9 nights in riads and boutique hotels","es":"9 noches en riads y hoteles boutique"},{"en":"A night at a luxury desert camp","es":"Noche en campamento de lujo en el desierto"},{"en":"Daily breakfast and {no.} dinners","es":"Desayunos diarios y {n°} cenas"},{"en":"Private transport for the whole trip","es":"Transporte privado durante todo el recorrido"},{"en":"Spanish-speaking local guides","es":"Guías locales en español"},{"en":"Wanna Go host for the entire trip","es":"Anfitriona de Wanna Go en todo el viaje"},{"en":"Hammam, cooking class and camel ride","es":"Hammam, clase de cocina y paseo en camello"},{"en":"Entrance fees to the itinerary''s monuments","es":"Entradas a los monumentos del itinerario"}],"ceja":{"en":"Everything clear from the start","es":"Todo claro desde el inicio"},"titulo":{"en":"What''s included","es":"Qué incluye"},"titulo_no":{"en":"Not included","es":"No incluido"},"titulo_si":{"en":"Included","es":"Incluido"}},"portada":{"alt":{"en":"Woman sitting in the Sahara dunes at sunset","es":"Mujer sentada en las dunas del Sahara al atardecer"},"foto":"mujer-dunas.jpg","datos":[{"texto":{"en":"days","es":"días"},"numero":"10"},{"texto":{"en":"destinations","es":"destinos"},"numero":"7"},{"texto":{"en":"travelers max.","es":"viajeras máx."},"numero":"16"}],"texto":{"en":"Ten days of blue medinas, mosaic palaces and a night under the Sahara stars. In a small group, with a Wanna Go host and everything taken care of. Purposeful travel, far from home too.","es":"Diez días entre medinas azules, palacios de mosaico y una noche bajo las estrellas del Sahara. En grupo pequeño, con anfitriona de Wanna Go y todo resuelto. Viajes con propósito, también lejos de casa."},"boton1":{"en":"Save my spot","es":"Quiero mi cupo"},"boton2":{"en":"See itinerary","es":"Ver itinerario"},"titulo":{"en":"Morocco","es":"Marruecos"},"etiqueta":{"en":"Women-only trip · Departs {2027}","es":"Viaje exclusivo para mujeres · Salida {2027}"},"titulo_resalte":{"en":"is yours","es":"es tuyo"}},"reserva":{"ceja":{"en":"Waiting list","es":"Lista de espera"},"foto":"camellos.jpg","boton":{"en":"Join the list","es":"Unirme a la lista"},"texto":{"en":"Leave your details and we''ll message you on WhatsApp with the full itinerary and the date bookings open.","es":"Déjanos tus datos y te escribimos por WhatsApp con el itinerario completo y la fecha de apertura de reservas."},"titulo":{"en":"Shall we head *to the desert?*","es":"¿Nos vamos *al desierto?*"}},"preguntas":{"ceja":{"en":"Frequently asked questions","es":"Preguntas frecuentes"},"lista":[{"pregunta":{"en":"Is Morocco safe for women?","es":"¿Es seguro Marruecos para mujeres?"},"respuesta":{"en":"Yes, traveling as a group with local guides. Before departure we send you a guide to dress and customs, and your host is with you the whole trip.","es":"Sí, viajando en grupo y con guías locales. Antes de salir te enviamos una guía de vestimenta y costumbres, y la anfitriona está contigo todo el viaje."}},{"pregunta":{"en":"Can I go alone, without knowing anyone?","es":"¿Puedo ir sola, sin conocer a nadie?"},"respuesta":{"en":"That''s the most common case. We pair you with a like-minded roommate, or you can pay the single room supplement.","es":"Es lo más común. Te asignamos compañera de habitación afín, o puedes pagar el suplemento de habitación individual."}},{"pregunta":{"en":"Do I need a visa?","es":"¿Necesito visa?"},"respuesta":{"en":"Colombian travelers need an e-visa {check current requirements}. We help you through the process.","es":"Las viajeras colombianas necesitan visa electrónica {verificar requisitos vigentes}. Te acompañamos en el trámite."}},{"pregunta":{"en":"How do payments work?","es":"¿Cómo son los pagos?"},"respuesta":{"en":"A deposit to book and the balance in {no.} installments. Payment methods {to be confirmed}.","es":"Anticipo para reservar y el saldo en {n°} cuotas. Medios de pago {por confirmar}."}},{"pregunta":{"en":"What fitness level do I need?","es":"¿Qué condición física necesito?"},"respuesta":{"en":"Basic. We walk through medinas and climb some stairs. The camel ride requires no experience.","es":"Básica. Caminamos por medinas y subimos algunas escaleras. El paseo en camello no requiere experiencia."}}],"titulo":{"en":"What everyone *asks*","es":"Lo que todas *preguntan*"}},"anfitriona":{"alt":{"es":"María Lucía Vásquez Cock, Luchy, fundadora de Wanna Go, en Cartagena","en":"María Lucía Vásquez Cock, Luchy, founder of Wanna Go, in Cartagena"},"ceja":{"en":"Your host","es":"Tu anfitriona"},"cita":{"en":"“I want every woman who travels with us to go home feeling braver than when she arrived.”","es":"“Quiero que cada mujer que viaje con nosotras vuelva sintiéndose más valiente de lo que llegó.”"},"foto":"luchy.jpg","firma":{"en":"María Lucía Vásquez Cock, Luchy · Founder of Wanna Go","es":"María Lucía Vásquez Cock, Luchy · Fundadora de Wanna Go"}},"itinerario":{"ceja":{"en":"Itinerary · 10 days","es":"Itinerario · 10 días"},"texto":{"en":"Five chapters, seven destinations. A relaxed pace, free time every day and experiences you can''t get traveling on your own.","es":"Cinco capítulos, siete destinos. Ritmo tranquilo, tiempo libre cada día y las experiencias que no se consiguen viajando por tu cuenta."},"titulo":{"en":"From the Atlantic *to the Sahara*","es":"Del Atlántico *al Sahara*"},"capitulos":[{"dias":{"en":"Days 1 – 2","es":"Días 1 – 2"},"foto":"marrakech.jpg","lugar":"Casablanca","texto":{"en":"Arrival, welcome dinner by the Atlantic and a first look at imperial architecture.","es":"Llegada, cena de bienvenida frente al Atlántico y primer contacto con la arquitectura imperial."},"titulo":{"en":"Casablanca and Rabat","es":"Casablanca y Rabat"},"detalle":[{"dia":{"en":"Day 1","es":"Día 1"},"texto":{"en":"Airport pickup, hotel and welcome dinner","es":"Recepción, hotel y cena de bienvenida"}},{"dia":{"en":"Day 2","es":"Día 2"},"texto":{"en":"Hassan II Mosque, Kasbah of the Udayas","es":"Mezquita Hassan II, Kasbah de los Oudayas"}}]},{"dias":{"en":"Day 3","es":"Día 3"},"foto":"chefchaouen.jpg","lugar":"Chefchaouen","texto":{"en":"Indigo-painted alleys in the Rif Mountains. A guided photo session and sunset from the Spanish Mosque.","es":"Callejones pintados de añil en las montañas del Rif. Sesión de fotos guiada y atardecer desde la mezquita española."},"titulo":{"en":"Chefchaouen, the blue city","es":"Chefchaouen, la ciudad azul"},"detalle":[{"dia":{"en":"Day 3","es":"Día 3"},"texto":{"en":"Local photographer {to be confirmed}","es":"Fotógrafa local {por confirmar}"}}]},{"dias":{"en":"Days 4 – 5","es":"Días 4 – 5"},"foto":"faroles.jpg","lugar":"Fez","texto":{"en":"More than nine thousand alleys, centuries-old tanneries and zellige workshops. A hammam ritual and a cooking class with a local family.","es":"Más de nueve mil callejones, curtiembres centenarias y talleres de zellige. Ritual de hammam y clase de cocina con una familia local."},"titulo":{"en":"Fez, the living medina","es":"Fez, la medina viva"},"detalle":[{"dia":{"en":"Day 4","es":"Día 4"},"texto":{"en":"Medina, Bou Inania Madrasa, tanneries","es":"Medina, madrasa Bou Inania, curtiembres"}},{"dia":{"en":"Day 5","es":"Día 5"},"texto":{"en":"Hammam and traditional cooking","es":"Hammam y cocina tradicional"}}]},{"dias":{"en":"Days 6 – 7","es":"Días 6 – 7"},"foto":"desierto.jpg","lugar":"Merzouga","texto":{"en":"We cross the Atlas through cedar forests to the dunes of Erg Chebbi. Arrival by camel, dinner under the stars and sunrise over the dunes.","es":"Cruzamos el Atlas por los bosques de cedros hasta las dunas de Erg Chebbi. Llegada en camello, cena bajo las estrellas y amanecer en las dunas."},"titulo":{"en":"The Sahara","es":"El Sahara"},"detalle":[{"dia":{"en":"Day 6","es":"Día 6"},"texto":{"en":"Drive through the Atlas, night in a luxury desert tent","es":"Ruta por el Atlas, noche en jaima de lujo"}},{"dia":{"en":"Day 7","es":"Día 7"},"texto":{"en":"Sunrise, Berber village and Gnawa music","es":"Amanecer, pueblo bereber y música gnawa"}}]},{"dias":{"en":"Day 8","es":"Día 8"},"foto":"kasbah.jpg","lugar":"Aït Ben Haddou","texto":{"en":"Todra Gorge, the Dades palm groves and the kasbah of Aït Ben Haddou, a UNESCO World Heritage Site.","es":"Gargantas del Todra, palmerales del Dades y la kasbah de Aït Ben Haddou, patrimonio de la UNESCO."},"titulo":{"en":"The road of a thousand kasbahs","es":"La ruta de las mil kasbahs"},"detalle":[]},{"dias":{"en":"Days 9 – 10","es":"Días 9 – 10"},"foto":"majorelle.jpg","lugar":"Marrakech","texto":{"en":"Majorelle Garden, Bahia Palace and the souks. Farewell on a rooftop overlooking Jemaa el-Fna square.","es":"Jardín Majorelle, palacio Bahía y los zocos. Despedida en un rooftop con vista a la plaza Jemaa el-Fna."},"titulo":{"en":"Marrakech, the red city","es":"Marrakech, la ciudad roja"},"detalle":[{"dia":{"en":"Day 9","es":"Día 9"},"texto":{"en":"Gardens, palaces and farewell dinner","es":"Jardines, palacios y cena de despedida"}},{"dia":{"en":"Day 10","es":"Día 10"},"texto":{"en":"Shopping and airport transfer","es":"Compras y traslado al aeropuerto"}}]}]}}'::jsonb) on conflict (id) do update set contenido = excluded.contenido;
insert into public.paginas (id, contenido) values ('nosotros', '{"seo":{"foto":"guatape-calle.jpg","titulo":{"en":"About us · Wanna Go, travel agency in Medellín","es":"Quiénes somos · Wanna Go, agencia de viajes en Medellín"},"descripcion":"Wanna Go es una agencia de turismo receptivo en Medellín fundada en 2019 por Luchy Vásquez. Viajes con propósito, auténticos y con hospitalidad cálida."},"cierre":{"foto":"grupo-atardecer.jpg","titulo":{"en":"Colombia is best experienced in good company","es":"Colombia se vive mejor en buena compañía"},"whatsapp":"Hola Wanna Go, quiero conocerlos."},"pilares":{"ceja":{"en":"03 · Our signature","es":"03 · Nuestro sello"},"items":[{"texto":{"en":"We support local businesses, respect the culture and protect the natural environment.","es":"Fomentamos el comercio local, respetamos la cultura y protegemos el entorno natural."},"titulo":{"en":"Local impact and sustainability","es":"Impacto local y sostenibilidad"}},{"texto":{"en":"We create space to learn, reconnect, pause and grow.","es":"Creamos espacios para aprender, reconectar, hacer una pausa y crecer."},"titulo":{"en":"Personal transformation","es":"Transformación personal"}},{"texto":{"en":"Genuine experiences, far from rushed mass tourism.","es":"Experiencias genuinas, lejos del turismo masivo y acelerado."},"titulo":{"en":"Authenticity and exclusivity","es":"Autenticidad y exclusividad"}},{"texto":{"en":"A personal touch of care and detail at every point of the trip.","es":"Un sello personal de cuidado y detalle en cada punto del viaje."},"titulo":{"en":"Warm hospitality","es":"Hospitalidad cálida"}}],"titulo":{"en":"The pillars of purposeful travel","es":"Pilares de los viajes con propósito"}},"portada":{"alt":{"en":"Street with colorful facades and zócalos in Guatapé","es":"Calle con fachadas de colores y zócalos en Guatapé"},"foto":"guatape-calle.jpg","texto":{"en":"We are an inbound travel agency founded in 2019. We show you Colombia from the inside: its people, its food and its landscapes.","es":"Somos una agencia de turismo receptivo fundada en 2019. Te mostramos Colombia desde adentro: con su gente, su cocina y sus paisajes."},"titulo":{"en":"Purposeful travel from Medellín","es":"Viajes con propósito desde Medellín"},"etiqueta":{"en":"About us","es":"Quiénes somos"}},"resenas":{"ceja":{"en":"What people say","es":"Lo que dicen"},"titulo":{"en":"Stories from people who traveled with us","es":"Historias de quienes viajaron con nosotros"}},"historia":{"alt":{"en":"Colorful houses and murals on the hillsides of Comuna 13","es":"Casas de colores y murales en las laderas de la Comuna 13"},"ceja":{"en":"01 · Our story","es":"01 · Nuestra historia"},"foto":"comuna13.jpg","cifras":[{"texto":{"en":"Year founded","es":"Año de fundación"},"valor":"2019"},{"texto":{"en":"National Tourism Registry","es":"Registro Nacional de Turismo"},"valor":"RNT 65568"},{"texto":{"en":"Colombia","es":"Colombia"},"valor":"Medellín"}],"titulo":{"en":"Purposeful travel","es":"Viajes con propósito"},"parrafos":[{"en":"Wanna Go is an inbound travel agency based in Medellín, founded in 2019 by María Lucía Vásquez Cock, Luchy.","es":"Wanna Go es una agencia de turismo receptivo con sede en Medellín, fundada en 2019 por María Lucía Vásquez Cock, Luchy."},{"en":"We steer clear of mass tourism and the predictable. We show you each destination from the inside, through its people, its food and its landscapes, so you come home different from how you left.","es":"Huimos del turismo masivo y de lo predecible. Te mostramos cada destino desde adentro, con su gente, su cocina y sus paisajes, para que vuelvas distinto de como te fuiste."}]},"fundadora":{"foto":"luchy.jpg","alt":{"es":"María Lucía Vásquez Cock, Luchy, fundadora de Wanna Go, en Cartagena","en":"María Lucía Vásquez Cock, Luchy, founder of Wanna Go, in Cartagena"},"ceja":{"en":"02 · Founder","es":"02 · Fundadora"},"cita":{"en":"“I believe in trips that transform you: the ones that seat you at a local family''s table and send you home with stories.”","es":"“Creo en los viajes que transforman: los que te sientan a la mesa de una familia local y te devuelven a casa con historias.”"},"cargo":{"en":"Founder and experience designer","es":"Fundadora y diseñadora de experiencias"},"nombre":"María Lucía Vásquez Cock · Luchy"}}'::jsonb) on conflict (id) do update set contenido = excluded.contenido;
insert into public.paginas (id, contenido) values ('popup', '{"popup":{"alt":{"en":"","es":""},"foto":"","aviso":{"en":"","es":""},"boton":{"en":"","es":""},"texto":{"en":"","es":""},"activo":true,"cerrar":{"en":"Not now","es":"Ahora no"},"enlace":"","titulo":{"en":"","es":""},"etiqueta":{"en":"","es":""},"titulo_resalte":{"en":"","es":""},"usar_temporada":true}}'::jsonb) on conflict (id) do update set contenido = excluded.contenido;
insert into public.paginas (id, contenido) values ('viajes-a-la-medida', '{"seo":{"foto":"salento.jpg","titulo":{"en":"Tailor-made trips across Colombia · Wanna Go Medellín","es":"Viajes a la medida por Colombia · Wanna Go Medellín"},"descripcion":"Itinerarios privados por Colombia diseñados alrededor de lo que te mueve: café, naturaleza, cocina, arte o descanso. Agencia en Medellín, RNT 65568."},"intro":{"alt":{"en":"Ripe coffee cherries on the branch","es":"Granos de café maduros en la rama"},"ceja":{"en":"01 · How we think about it","es":"01 · Cómo lo pensamos"},"foto":"cafe.jpg","titulo":{"en":"A trip that feels like you","es":"Un viaje que se parece a ti"},"parrafos":[{"en":"We don''t sell fixed packages. We start with a conversation: what excites you, who you are traveling with, how much time you have and the pace you want.","es":"No trabajamos con paquetes cerrados. Empezamos por una conversación: qué te emociona, con quién viajas, cuánto tiempo tienes y a qué ritmo quieres moverte."},{"en":"From there we design a route through Colombia with lodging, local guides and experiences we choose one by one. During the trip, we are there for you.","es":"Con eso diseñamos una ruta por Colombia con alojamientos, guías locales y experiencias que elegimos una por una. Durante el viaje, estamos pendientes de ti."}]},"pasos":{"ceja":{"en":"02 · Step by step","es":"02 · Paso a paso"},"items":[{"texto":{"en":"What you want to experience, dates, budget and who''s traveling.","es":"Qué quieres vivir, fechas, presupuesto y quién viaja."},"titulo":{"en":"Tell us","es":"Nos cuentas"}},{"texto":{"en":"A day-by-day itinerary with lodging and experiences.","es":"Un itinerario día a día con alojamientos y experiencias."},"titulo":{"en":"We propose","es":"Te proponemos"}},{"texto":{"en":"We adjust whatever is needed until it''s truly your trip.","es":"Cambiamos lo necesario hasta que sea tu viaje."},"titulo":{"en":"We fine-tune","es":"Lo ajustamos"}},{"texto":{"en":"Logistics handled and a direct line to us.","es":"Logística resuelta y contacto directo con nosotros."},"titulo":{"en":"You travel at ease","es":"Viajas tranquilo"}}],"titulo":{"en":"How we design your trip","es":"Así diseñamos tu viaje"}},"cierre":{"foto":"guatape.jpg","titulo":{"en":"Shall we start designing it?","es":"¿Empezamos a diseñarlo?"},"whatsapp":"Hola Wanna Go, quiero un viaje a la medida."},"portada":{"alt":{"en":"Wax palms in the Cocora Valley","es":"Palmas de cera en el valle de Cocora"},"foto":"salento.jpg","texto":{"en":"Private itineraries designed around what moves you: coffee, nature, food, art or rest.","es":"Itinerarios privados diseñados alrededor de lo que te mueve: café, naturaleza, cocina, arte o descanso."},"titulo":{"en":"Tailor-made trips across Colombia","es":"Viajes a la medida por Colombia"},"etiqueta":{"en":"At your pace","es":"A tu ritmo"},"whatsapp":"Hola Wanna Go, quiero un viaje a la medida."},"resenas":{"ceja":{"en":"What people say","es":"Lo que dicen"},"titulo":{"en":"Stories from people who traveled with us","es":"Historias de quienes viajaron con nosotros"}},"destinos":{"ceja":{"en":"03 · Inspiration","es":"03 · Inspiración"},"lista":["guatape","eje-cafetero","cartagena"],"titulo":{"en":"Destinations to start with","es":"Destinos para empezar"}}}'::jsonb) on conflict (id) do update set contenido = excluded.contenido;
insert into public.paginas (id, contenido) values ('viajes-grupales', '{"seo":{"foto":"grupo-atardecer.jpg","titulo":{"en":"Group trips with a host · Wanna Go Colombia","es":"Viajes grupales con anfitriona · Wanna Go Colombia"},"descripcion":"Salidas con fecha fija y grupos pequeños, con anfitriona de Wanna Go de principio a fin. Marruecos entre mujeres, Cartagena y el Eje Cafetero."},"intro":{"alt":{"en":"Traveler in the Sahara dunes at sunset","es":"Viajera en las dunas del Sahara al atardecer"},"ceja":{"en":"01 · How we travel","es":"01 · Cómo viajamos"},"foto":"mujer-dunas.jpg","titulo":{"en":"Group travel that doesn''t feel like a tour","es":"Viajar en grupo, sin sentirte en un tour"},"parrafos":[{"en":"Our group departures are for just a few people, with a carefully planned itinerary and free time to explore your own way.","es":"Nuestras salidas grupales son para pocas personas, con un itinerario pensado al detalle y tiempo libre para explorar a tu manera."},{"en":"A Wanna Go host travels with you from start to finish and takes care of the logistics, so all you have to do is enjoy the trip.","es":"Una anfitriona de Wanna Go viaja contigo de principio a fin. Se encarga de la logística para que tú solo te ocupes de vivir el viaje."}]},"cierre":{"foto":"camellos.jpg","titulo":{"en":"Want to hear about upcoming departures?","es":"¿Quieres saber de las próximas salidas?"},"whatsapp":"Hola Wanna Go, quiero información de los viajes grupales."},"portada":{"alt":{"en":"Group of travelers watching the sunset","es":"Grupo de viajeros contemplando el atardecer"},"foto":"grupo-atardecer.jpg","texto":{"en":"Fixed-date departures, small groups and a Wanna Go host with you every step of the way.","es":"Salidas con fecha fija, grupos pequeños y una anfitriona de Wanna Go acompañándote todo el camino."},"titulo":{"en":"Group trips with a host","es":"Viajes grupales con anfitriona"},"etiqueta":{"en":"Small groups","es":"Grupos pequeños"},"whatsapp":"Hola Wanna Go, quiero información de los viajes grupales."},"resenas":{"ceja":{"en":"What people say","es":"Lo que dicen"},"titulo":{"en":"Stories from people who traveled with us","es":"Historias de quienes viajaron con nosotros"}},"salidas":{"ceja":{"en":"02 · Upcoming departures","es":"02 · Próximas salidas"},"titulo":{"en":"Choose your next trip","es":"Elige tu próximo viaje"},"proximas":[{"alt":{"en":"Colonial street in Cartagena with lanterns","es":"Calle colonial de Cartagena con faroles"},"foto":"cartagena.jpg","aviso":{"en":"Coming soon","es":"Próximamente"},"fecha":{"en":"Date to be confirmed","es":"Fecha por definir"},"enlace":"destinos/cartagena/","titulo":{"en":"Cartagena and the Caribbean","es":"Cartagena y el Caribe"},"fecha_por_definir":true},{"alt":{"en":"Ripe coffee cherries on the branch","es":"Granos de café maduros en la rama"},"foto":"cafe.jpg","aviso":{"en":"Coming soon","es":"Próximamente"},"fecha":{"en":"Date to be confirmed","es":"Fecha por definir"},"enlace":"destinos/eje-cafetero/","titulo":{"en":"Coffee Cultural Landscape","es":"Paisaje Cultural Cafetero"},"fecha_por_definir":true}]},"siempre":{"ceja":{"en":"03 · On every departure","es":"03 · En cada salida"},"items":[{"texto":{"en":"Few people, so you travel calmly and get to know each other.","es":"Pocas personas, para viajar con calma y conocerse."},"titulo":{"en":"Small groups","es":"Grupos pequeños"}},{"texto":{"en":"With you from departure to return.","es":"Te acompaña desde la salida hasta el regreso."},"titulo":{"en":"A Wanna Go host","es":"Anfitriona Wanna Go"}},{"texto":{"en":"Food, culture and people at every destination.","es":"Cocina, cultura y gente de cada destino."},"titulo":{"en":"Local experiences","es":"Experiencias locales"}},{"texto":{"en":"Lodging, transfers and bookings taken care of.","es":"Alojamiento, traslados y reservas resueltos."},"titulo":{"en":"Everything organized","es":"Todo organizado"}}],"titulo":{"en":"What you always get","es":"Lo que siempre tienes"}}}'::jsonb) on conflict (id) do update set contenido = excluded.contenido;
insert into public.destinos (url, orden, nombre, h1, region, corto, foto, alt, foto2, alt2, titulo_seo, descripcion_seo, lead, h2, parrafos, vivir, datos, otros) values ('guatape', 1, '{"en":"Guatapé","es":"Guatapé 1"}'::jsonb, '{"en":"Guatapé and the Piedra del Peñol","es":"Guatapé y la Piedra del Peñol"}'::jsonb, '{"en":"Antioquia · 2 hours from Medellín","es":"Antioquia · a 2 horas de Medellín"}'::jsonb, '{"en":"Colorful zócalos and the Piedra del Peñol.","es":"Zócalos de colores y la Piedra del Peñol."}'::jsonb, 'guatape.jpg', '{"en":"Guatapé reservoir and its green islands seen from above","es":"Embalse de Guatapé con sus islas verdes visto desde lo alto"}'::jsonb, 'guatape-calle.jpg', '{"en":"Street with colorful facades and zócalos in Guatapé","es":"Calle con fachadas de colores y zócalos en Guatapé"}'::jsonb, '{"en":"Guatapé and the Piedra del Peñol from Medellín · Wanna Go","es":"Guatapé y la Piedra del Peñol desde Medellín · Wanna Go"}'::jsonb, 'Viaje a Guatapé desde Medellín: sube la Piedra del Peñol, recorre las calles de zócalos y navega el embalse. Diseñado a tu medida por Wanna Go.', '{"en":"The town of painted zócalos and the rock that looks out over a sea of islands. Two hours from Medellín, one of the most photographed landscapes in Colombia.","es":"El pueblo de los zócalos y la piedra que mira sobre un mar de islas. A dos horas de Medellín, uno de los paisajes más fotografiados de Colombia."}'::jsonb, '{"en":"Color, water and mountains","es":"Color, agua y montaña"}'::jsonb, '[{"en":"Guatapé is a town of cobbled streets where every house tells its story through its zócalos: colorful reliefs along the base of the façades depicting trades, animals and scenes of local life.","es":"Guatapé es un pueblo de calles empedradas donde cada casa cuenta su historia en los zócalos: relieves de colores en la base de las fachadas que muestran oficios, animales y escenas de la vida local."},{"en":"Nearby stands the Piedra del Peñol. Those who climb its more than 700 steps are rewarded with a full view of the reservoir, its islands and green peninsulas. With us you explore it unhurried, with time for the water, local food and conversation.","es":"Muy cerca está la Piedra del Peñol. Quien sube sus más de 700 escalones encuentra arriba una vista completa del embalse, con sus islas y penínsulas verdes. Con nosotros lo recorres sin afán, con tiempo para el agua, la cocina local y la conversación."}]'::jsonb, '[{"texto":{"en":"More than 700 steps up to one of the widest views in Antioquia.","es":"Más de 700 escalones y una de las vistas más amplias de Antioquia."},"titulo":{"en":"Climb the Piedra del Peñol","es":"Subir la Piedra del Peñol"}},{"texto":{"en":"A walk past the painted façades and the stories they tell.","es":"Un recorrido a pie por las fachadas pintadas y sus historias."},"titulo":{"en":"Streets of zócalos","es":"Calles de zócalos"}},{"texto":{"en":"Boat or sailboat among islands, bays and lakeside farms.","es":"Lancha o velero entre islas, bahías y fincas a la orilla del agua."},"titulo":{"en":"Out on the reservoir","es":"Paseo por el embalse"}},{"texto":{"en":"Trout, bandeja paisa and regional desserts at places we know well.","es":"Trucha, bandeja paisa y postres de la región en lugares que conocemos."},"titulo":{"en":"Small-town cooking","es":"Cocina de pueblo"}}]'::jsonb, '{"epoca":{"en":"Year-round","es":"Todo el año"},"ideal":{"en":"Families, couples and groups","es":"Familias, parejas y grupos"},"llegar":{"en":"2 hours by road from Medellín","es":"2 horas por carretera desde Medellín"},"tiempo":{"en":"1 or 2 days","es":"1 o 2 días"}}'::jsonb, array['comuna-13', 'eje-cafetero', 'plazas-de-mercado']::text[]);
insert into public.destinos (url, orden, nombre, h1, region, corto, foto, alt, foto2, alt2, titulo_seo, descripcion_seo, lead, h2, parrafos, vivir, datos, otros) values ('comuna-13', 2, '{"en":"Comuna 13","es":"Comuna 13"}'::jsonb, '{"en":"Comuna 13, Medellín","es":"Comuna 13, Medellín"}'::jsonb, '{"en":"Medellín · San Javier district","es":"Medellín · barrio San Javier"}'::jsonb, '{"en":"Graffiti, hip hop and a story of transformation.","es":"Grafiti, hip hop y una historia de transformación."}'::jsonb, 'comuna13.jpg', '{"en":"Colorful houses and murals on the hillsides of Comuna 13","es":"Casas de colores y murales en las laderas de la Comuna 13"}'::jsonb, 'medellin-montanas.jpg', '{"en":"Medellín buildings against the mountains","es":"Edificios de Medellín frente a las montañas"}'::jsonb, '{"en":"Comuna 13 tour in Medellín · Wanna Go","es":"Tour por la Comuna 13 de Medellín · Wanna Go"}'::jsonb, 'Recorre la Comuna 13 de Medellín con guías del barrio: grafitis, escaleras eléctricas, hip hop y la historia de su transformación. Con Wanna Go.', '{"en":"Graffiti, hip hop and open-air escalators in the neighborhood that became a symbol of Medellín''s transformation.","es":"Grafitis, hip hop y escaleras eléctricas al aire libre en el barrio que se convirtió en símbolo de la transformación de Medellín."}'::jsonb, '{"en":"A story told from the inside","es":"Una historia contada desde adentro"}'::jsonb, '[{"en":"Comuna 13 went from being one of the toughest places in Medellín to one of its most visited neighborhoods. Its painted walls, street music and the escalators climbing the hillside tell that change better than any book.","es":"La Comuna 13 pasó de ser uno de los lugares más difíciles de Medellín a uno de sus barrios más visitados. Sus muros pintados, la música en la calle y las escaleras eléctricas que suben la ladera cuentan ese cambio mejor que cualquier libro."},{"en":"You walk it with guides who were born and raised in the neighborhood. They show you their streets, introduce you to local artists and explain the meaning behind each mural.","es":"Lo recorres con guías que nacieron y crecieron en el barrio. Ellos te muestran sus calles, te presentan a artistas locales y te explican el significado de cada mural."}]'::jsonb, '[{"texto":{"en":"The key murals, explained by the people who watched them being painted.","es":"Los murales más importantes, explicados por quienes los vieron nacer."},"titulo":{"en":"Graffiti tour","es":"Grafitour"}},{"texto":{"en":"A ride up the escalators that changed life on the hillside.","es":"El recorrido por las escaleras que cambiaron la vida de la ladera."},"titulo":{"en":"Outdoor escalators","es":"Escaleras eléctricas"}},{"texto":{"en":"Street music and dance with local crews.","es":"Música y baile en la calle con los grupos del barrio."},"titulo":{"en":"Hip hop and dance","es":"Hip hop y baile"}},{"texto":{"en":"Handmade ice pops, empanadas and coffee at local businesses.","es":"Paletas artesanales, empanadas y café en negocios locales."},"titulo":{"en":"Neighborhood flavors","es":"Sabores del barrio"}}]'::jsonb, '{"epoca":{"en":"Year-round","es":"Todo el año"},"ideal":{"en":"Curious travelers and groups","es":"Viajeros curiosos y grupos"},"llegar":{"en":"In Medellín, from the San Javier metro station","es":"En Medellín, desde la estación San Javier del metro"},"tiempo":{"en":"Half a day","es":"Medio día"}}'::jsonb, array['plazas-de-mercado', 'guatape', 'cartagena']::text[]);
insert into public.destinos (url, orden, nombre, h1, region, corto, foto, alt, foto2, alt2, titulo_seo, descripcion_seo, lead, h2, parrafos, vivir, datos, otros) values ('cartagena', 3, '{"en":"Cartagena","es":"Cartagena"}'::jsonb, '{"en":"Cartagena de Indias","es":"Cartagena de Indias"}'::jsonb, '{"en":"Colombian Caribbean · Bolívar","es":"Caribe colombiano · Bolívar"}'::jsonb, '{"en":"The walled city and the Caribbean Sea.","es":"La ciudad amurallada y el mar Caribe."}'::jsonb, 'cartagena-casas.jpg', '{"en":"Colorful colonial houses in the historic center of Cartagena","es":"Casas coloniales de colores en el centro histórico de Cartagena"}'::jsonb, 'cartagena.jpg', '{"en":"Colonial street in Cartagena with lanterns","es":"Calle colonial de Cartagena con faroles"}'::jsonb, '{"en":"Tailor-made trip to Cartagena de Indias · Wanna Go","es":"Viaje a Cartagena de Indias a tu medida · Wanna Go"}'::jsonb, 'Viaje a Cartagena a tu medida: ciudad amurallada, Getsemaní e Islas del Rosario, con hoteles boutique y guías locales. Diseñado desde Medellín por Wanna Go.', '{"en":"City walls, flower-draped balconies and sunsets over the Caribbean. The walled city seen calmly, away from the usual route.","es":"Murallas, balcones con flores y atardeceres sobre el Caribe. La ciudad amurallada vista con calma, lejos del recorrido de siempre."}'::jsonb, '{"en":"A city meant to be walked slowly","es":"La ciudad que se camina despacio"}'::jsonb, '[{"en":"Cartagena''s historic center, with its port, fortresses and monumental ensemble, has been a UNESCO World Heritage Site since 1984. Its colonial streets, squares and colorful houses are best enjoyed on foot, at a Caribbean pace.","es":"El centro histórico de Cartagena, con su puerto, sus fortalezas y su conjunto monumental, es Patrimonio de la Humanidad de la UNESCO desde 1984. Sus calles coloniales, plazas y casas de colores se disfrutan mejor a pie, al ritmo del Caribe."},{"en":"We design your trip combining the walled city, the Getsemaní neighborhood and the sea around the Rosario Islands, with boutique hotels and restaurants we have tried ourselves.","es":"Diseñamos tu viaje combinando la ciudad amurallada, el barrio de Getsemaní y el mar de las Islas del Rosario, con hoteles boutique y restaurantes que hemos probado."}]'::jsonb, '[{"texto":{"en":"Squares, churches and balconies with a local guide.","es":"Plazas, iglesias y balcones con un guía local."},"titulo":{"en":"The walled city","es":"Ciudad amurallada"}},{"texto":{"en":"Murals, music and neighborhood life as evening falls.","es":"Murales, música y la vida de barrio al caer la tarde."},"titulo":{"en":"Getsemaní","es":"Getsemaní"}},{"texto":{"en":"A day of turquoise water and quiet beaches.","es":"Un día de mar turquesa y playas tranquilas."},"titulo":{"en":"Rosario Islands","es":"Islas del Rosario"}},{"texto":{"en":"Fresh fish, coconut rice and tropical fruit.","es":"Pescado fresco, arroz con coco y frutas tropicales."},"titulo":{"en":"Caribbean cuisine","es":"Cocina del Caribe"}}]'::jsonb, '{"epoca":{"en":"December to April, the driest season","es":"De diciembre a abril, la temporada más seca"},"ideal":{"en":"Couples, friends and celebrations","es":"Parejas, amigas y celebraciones"},"llegar":{"en":"Direct flight from Medellín","es":"Vuelo directo desde Medellín"},"tiempo":{"en":"3 to 4 days","es":"3 a 4 días"}}'::jsonb, array['tayrona', 'eje-cafetero', 'guatape']::text[]);
insert into public.destinos (url, orden, nombre, h1, region, corto, foto, alt, foto2, alt2, titulo_seo, descripcion_seo, lead, h2, parrafos, vivir, datos, otros) values ('valle-de-cocora', 4, '{"en":"Cocora Valley","es":"Valle de Cocora"}'::jsonb, '{"en":"Cocora Valley and Salento","es":"Valle de Cocora y Salento"}'::jsonb, '{"en":"Quindío · Coffee Region","es":"Quindío · Eje Cafetero"}'::jsonb, '{"en":"Hikes among the wax palms.","es":"Caminatas entre las palmas de cera."}'::jsonb, 'salento.jpg', '{"en":"Wax palms in the Cocora Valley","es":"Palmas de cera en el valle de Cocora"}'::jsonb, 'cafe.jpg', '{"en":"Ripe coffee cherries on the branch","es":"Granos de café maduros en la rama"}'::jsonb, '{"en":"Cocora Valley and Salento: wax palms · Wanna Go","es":"Valle de Cocora y Salento: palmas de cera · Wanna Go"}'::jsonb, 'Camina entre las palmas de cera del Valle de Cocora, conoce Salento y visita una finca cafetera. Viaje al Quindío diseñado por Wanna Go.', '{"en":"Walk among wax palms, Colombia''s national tree, in a misty mountain valley just outside Salento.","es":"Caminar entre palmas de cera, el árbol nacional de Colombia, en un valle de niebla y montaña a las afueras de Salento."}'::jsonb, '{"en":"The valley of the tallest palms","es":"El valle de las palmas más altas"}'::jsonb, '[{"en":"The Quindío wax palm is Colombia''s national tree and one of the tallest palms in the world: it can reach 60 meters. Hundreds of them rise over green pastures and mist-covered slopes in the Cocora Valley.","es":"La palma de cera del Quindío es el árbol nacional de Colombia y una de las palmas más altas del mundo: puede llegar a los 60 metros. En el Valle de Cocora crecen cientos de ellas sobre potreros verdes y laderas cubiertas de niebla."},{"en":"We pair the hike with Salento, one of the most traditional towns in the Coffee Region, and with a coffee farm to understand coffee from seed to cup.","es":"Combinamos la caminata con Salento, uno de los pueblos más tradicionales del Eje Cafetero, y con una finca cafetera para entender el café desde la semilla hasta la taza."}]'::jsonb, '[{"texto":{"en":"Trails for different levels, at your own pace.","es":"Senderos de distintos niveles, a tu ritmo."},"titulo":{"en":"Hike among the palms","es":"Caminata entre palmas"}},{"texto":{"en":"Calle Real, colorful balconies and local crafts.","es":"Calle Real, balcones de colores y artesanías."},"titulo":{"en":"Salento","es":"Salento"}},{"texto":{"en":"Picking, roasting and tasting with growers.","es":"Recolección, tostión y cata con productores."},"titulo":{"en":"Coffee farm","es":"Finca cafetera"}},{"texto":{"en":"The valley''s classic dish, with mountain views.","es":"El plato típico del valle, frente a las montañas."},"titulo":{"en":"Trout and patacón","es":"Trucha y patacón"}}]'::jsonb, '{"epoca":{"en":"Year-round; mornings tend to be clearer","es":"Todo el año; las mañanas suelen ser más despejadas"},"ideal":{"en":"Nature and hiking lovers","es":"Amantes de la naturaleza y la caminata"},"llegar":{"en":"Flight to Pereira or Armenia, then 1 hour by road","es":"Vuelo a Pereira o Armenia y 1 hora por carretera"},"tiempo":{"en":"2 or 3 days including Salento","es":"2 o 3 días con Salento"}}'::jsonb, array['eje-cafetero', 'guatape', 'tayrona']::text[]);
insert into public.destinos (url, orden, nombre, h1, region, corto, foto, alt, foto2, alt2, titulo_seo, descripcion_seo, lead, h2, parrafos, vivir, datos, otros) values ('tayrona', 5, '{"en":"Tayrona Park","es":"Parque Tayrona"}'::jsonb, '{"en":"Tayrona National Natural Park","es":"Parque Nacional Natural Tayrona"}'::jsonb, '{"en":"Colombian Caribbean · Magdalena","es":"Caribe colombiano · Magdalena"}'::jsonb, '{"en":"Jungle and beaches at the foot of the Sierra Nevada.","es":"Selva y playas al pie de la Sierra Nevada."}'::jsonb, 'tayrona.jpg', '{"en":"Tayrona Park beach with jungle and boulders by the sea","es":"Playa del Parque Tayrona con selva y rocas junto al mar"}'::jsonb, 'grupo-atardecer.jpg', '{"en":"Group of travelers watching the sunset","es":"Grupo de viajeros contemplando el atardecer"}'::jsonb, '{"en":"Trip to Tayrona Park with Wanna Go","es":"Viaje al Parque Tayrona con Wanna Go"}'::jsonb, 'Viaje al Parque Tayrona: senderos de selva, Cabo San Juan y la cultura de la Sierra Nevada de Santa Marta, con guías locales. Diseñado por Wanna Go.', '{"en":"Jungle that runs down from the Sierra Nevada to golden-sand beaches. A national park to explore respectfully and unhurried.","es":"Selva que baja de la Sierra Nevada hasta playas de arena dorada. Un parque nacional para recorrer con respeto y sin prisa."}'::jsonb, '{"en":"Where the mountains meet the sea","es":"Donde la sierra se encuentra con el mar"}'::jsonb, '[{"en":"Tayrona National Natural Park, near Santa Marta, protects forests, bays and beaches at the foot of the Sierra Nevada de Santa Marta, ancestral land of the Kogi, Arhuaco, Wiwa and Kankuamo peoples.","es":"El Parque Nacional Natural Tayrona, cerca de Santa Marta, protege bosques, bahías y playas al pie de la Sierra Nevada de Santa Marta, territorio ancestral de los pueblos kogui, arhuaco, wiwa y kankuamo."},{"en":"We plan your visit with local guides, nearby lodging and the park schedule, since it closes for a few periods each year to let the ecosystem rest. We confirm the dates before booking.","es":"Organizamos tu visita con guías locales, alojamiento en la zona y los tiempos del parque, que cierra algunas temporadas al año para su descanso ecológico. Te confirmamos las fechas antes de reservar."}]'::jsonb, '[{"texto":{"en":"Walks through tropical forest, monkeys and giant boulders.","es":"Caminatas entre bosque tropical, monos y rocas gigantes."},"titulo":{"en":"Jungle trails","es":"Senderos de selva"}},{"texto":{"en":"One of the most beautiful beaches on Colombia''s Caribbean coast.","es":"Una de las playas más bonitas del Caribe colombiano."},"titulo":{"en":"Cabo San Juan","es":"Cabo San Juan"}},{"texto":{"en":"An introduction to the worldview of the Sierra Nevada''s Indigenous peoples.","es":"Un acercamiento a la visión de los pueblos indígenas de la Sierra Nevada."},"titulo":{"en":"Culture of the Sierra","es":"Cultura de la Sierra"}},{"texto":{"en":"Colombia''s oldest city, as your base.","es":"La ciudad más antigua de Colombia, como base del viaje."},"titulo":{"en":"Santa Marta","es":"Santa Marta"}}]'::jsonb, '{"epoca":{"en":"December to April, the driest season","es":"De diciembre a abril, la temporada más seca"},"ideal":{"en":"Nature, sea and gentle adventure","es":"Naturaleza, mar y aventura suave"},"llegar":{"en":"Direct flight to Santa Marta, then 1 hour by road","es":"Vuelo directo a Santa Marta y 1 hora por carretera"},"tiempo":{"en":"3 to 4 days","es":"3 a 4 días"}}'::jsonb, array['cartagena', 'valle-de-cocora', 'comuna-13']::text[]);
insert into public.destinos (url, orden, nombre, h1, region, corto, foto, alt, foto2, alt2, titulo_seo, descripcion_seo, lead, h2, parrafos, vivir, datos, otros) values ('eje-cafetero', 6, '{"en":"Coffee Region","es":"Eje Cafetero"}'::jsonb, '{"en":"Coffee Region","es":"Eje Cafetero"}'::jsonb, '{"en":"Caldas, Risaralda and Quindío","es":"Caldas, Risaralda y Quindío"}'::jsonb, '{"en":"Farms, villages and single-origin coffee.","es":"Fincas, pueblos y café de origen."}'::jsonb, 'cafe.jpg', '{"en":"Ripe coffee cherries on the branch","es":"Granos de café maduros en la rama"}'::jsonb, 'salento.jpg', '{"en":"Wax palms in the Cocora Valley","es":"Palmas de cera en el valle de Cocora"}'::jsonb, '{"en":"Trip to the Coffee Region: farms and coffee · Wanna Go","es":"Viaje al Eje Cafetero: fincas y café · Wanna Go"}'::jsonb, 'Viaje al Eje Cafetero de Colombia: fincas cafeteras, Salento, Filandia y el Valle de Cocora, en el Paisaje Cultural Cafetero. Diseñado por Wanna Go.', '{"en":"Coffee-planted mountains, bahareque villages and farms where the day starts with a freshly brewed cup.","es":"Montañas sembradas de café, pueblos de bahareque y fincas donde el día empieza con una taza recién hecha."}'::jsonb, '{"en":"A landscape that is World Heritage","es":"Un paisaje que es patrimonio"}'::jsonb, '[{"en":"Colombia''s Coffee Cultural Landscape has been a UNESCO World Heritage Site since 2011. It recognizes a way of life: families who have grown coffee on steep slopes for generations and villages with colorful architecture.","es":"El Paisaje Cultural Cafetero de Colombia es Patrimonio Mundial de la UNESCO desde 2011. Reconoce una forma de vida: familias que cultivan café en laderas empinadas desde hace generaciones y pueblos con arquitectura de colores."},{"en":"We take you to farms where growers share their craft, to villages like Filandia and Salento, and to landscapes like the Cocora Valley. Staying on a farm is part of the trip.","es":"Te llevamos a fincas donde los productores te enseñan su oficio, a pueblos como Filandia y Salento, y a paisajes como el Valle de Cocora. Dormir en una finca es parte del viaje."}]'::jsonb, '[{"texto":{"en":"Picking, drying, roasting and tasting with a coffee-growing family.","es":"Recolección, secado, tostión y cata con una familia cafetera."},"titulo":{"en":"From bean to cup","es":"Del grano a la taza"}},{"texto":{"en":"Villages of colorful balconies and lookouts.","es":"Pueblos de balcones de colores y miradores."},"titulo":{"en":"Filandia and Salento","es":"Filandia y Salento"}},{"texto":{"en":"Traditional houses surrounded by coffee plantations.","es":"Casas tradicionales rodeadas de cafetales."},"titulo":{"en":"Stay on a farm","es":"Dormir en una finca"}},{"texto":{"en":"Hot springs, birdwatching and botanical gardens.","es":"Aguas termales, avistamiento de aves y jardines botánicos."},"titulo":{"en":"Hot springs and nature","es":"Termales y naturaleza"}}]'::jsonb, '{"epoca":{"en":"Year-round; the main harvest runs from September to December","es":"Todo el año; la cosecha principal va de septiembre a diciembre"},"ideal":{"en":"Coffee lovers, families and couples","es":"Amantes del café, familias y parejas"},"llegar":{"en":"Flight to Pereira or Armenia, or 5 to 6 hours by road from Medellín","es":"Vuelo a Pereira o Armenia, o 5 a 6 horas por carretera desde Medellín"},"tiempo":{"en":"3 to 5 days","es":"3 a 5 días"}}'::jsonb, array['valle-de-cocora', 'guatape', 'plazas-de-mercado']::text[]);
insert into public.destinos (url, orden, nombre, h1, region, corto, foto, alt, foto2, alt2, titulo_seo, descripcion_seo, lead, h2, parrafos, vivir, datos, otros) values ('plazas-de-mercado', 7, '{"en":"Local markets","es":"Plazas de mercado"}'::jsonb, '{"en":"Medellín''s market halls","es":"Plazas de mercado de Medellín"}'::jsonb, '{"en":"Medellín","es":"Medellín"}'::jsonb, '{"en":"Exotic fruit and home-style cooking.","es":"Frutas exóticas y cocina popular."}'::jsonb, 'frutas.jpg', '{"en":"Tropical fruit stall at a market hall","es":"Puesto de frutas tropicales en una plaza de mercado"}'::jsonb, 'medellin.jpg', '{"en":"Medellín lit up at dusk, surrounded by mountains","es":"Medellín iluminada al atardecer, rodeada de montañas"}'::jsonb, '{"en":"Fruit tour in Medellín market halls · Wanna Go","es":"Tour de frutas en plazas de mercado de Medellín · Wanna Go"}'::jsonb, 'Tour de frutas exóticas por las plazas de mercado de Medellín: cata en el puesto, yerbateros y almuerzo típico, con guías locales de Wanna Go.', '{"en":"Lulo, granadilla, passion fruit, soursop. Colombia is tasted in its market halls, among stalls of fruit, herbs and home-style cooking.","es":"Lulo, granadilla, maracuyá, guanábana. Colombia se prueba en sus plazas de mercado, entre puestos de frutas, hierbas y cocina popular."}'::jsonb, '{"en":"Medellín''s pantry","es":"La despensa de Medellín"}'::jsonb, '[{"en":"Market halls are where all of Antioquia meets: farmers, cooks, herbalists and vendors who have spent a lifetime at the same stall. Colombia has an enormous variety of fruit, and here you see it, smell it and taste it.","es":"Las plazas de mercado son el lugar donde se cruza todo Antioquia: campesinos, cocineras, yerbateros y vendedores que llevan toda la vida en el mismo puesto. Colombia tiene una enorme variedad de frutas y aquí se ve, se huele y se prueba."},{"en":"We walk through market halls like La Minorista with local guides, taste fruit you won''t find anywhere else and finish at the table with a traditional lunch.","es":"Recorremos plazas como la Minorista con guías locales, probamos frutas que no encontrarás en otro país y terminamos en la mesa, con un almuerzo típico."}]'::jsonb, '[{"texto":{"en":"Exotic fruits explained and tasted right at the stall.","es":"Frutas exóticas explicadas y probadas en el puesto."},"titulo":{"en":"Fruit tasting","es":"Cata de frutas"}},{"texto":{"en":"Herbalists and their traditional remedies.","es":"Los yerbateros y sus remedios tradicionales."},"titulo":{"en":"Herbs and folk wisdom","es":"Hierbas y saberes"}},{"texto":{"en":"Soup, beans or sancocho where the market workers eat.","es":"Sopa, frijoles o sancocho donde comen los que trabajan ahí."},"titulo":{"en":"Market lunch","es":"Almuerzo de plaza"}},{"texto":{"en":"A paisa breakfast to start the day.","es":"Desayuno paisa para empezar con energía."},"titulo":{"en":"Coffee and arepa","es":"Café y arepa"}}]'::jsonb, '{"epoca":{"en":"Year-round, best in the morning","es":"Todo el año, mejor en la mañana"},"ideal":{"en":"Curious travelers and food lovers","es":"Viajeros curiosos y amantes de la cocina"},"llegar":{"en":"In Medellín, near downtown","es":"En Medellín, cerca del centro"},"tiempo":{"en":"Half a day","es":"Medio día"}}'::jsonb, array['comuna-13', 'guatape', 'eje-cafetero']::text[]);
insert into public.temporadas (orden, activo, hasta, enlace, foto, alt, titulo, titulo_resalte, etiqueta, aviso, resumen, datos, salida, salida_por_definir, boton) values (1, true, null, 'marruecos/', 'mujer-dunas.jpg', '{"en":"Traveler sitting in the Sahara dunes at sunset","es":"Viajera sentada en las dunas del Sahara al atardecer"}'::jsonb, '{"en":"Morocco","es":"Marruecos"}'::jsonb, '{"en":"among women","es":"entre mujeres"}'::jsonb, '{"en":"Group trip · Women only","es":"Viaje grupal · Solo mujeres"}'::jsonb, '{"en":"Spots open","es":"Cupos abiertos"}'::jsonb, '{"en":"Blue medinas, mosaic palaces and a night under the Sahara stars. A small group, with a Wanna Go host from start to finish.","es":"Medinas azules, palacios de mosaico y una noche bajo las estrellas del Sahara. Grupo pequeño, con anfitriona de Wanna Go de principio a fin."}'::jsonb, '[{"texto":{"en":"days","es":"días"},"numero":"10"},{"texto":{"en":"destinations","es":"destinos"},"numero":"7"},{"texto":{"en":"travelers max.","es":"viajeras máx."},"numero":"16"}]'::jsonb, '2027', true, '{"en":"See the trip","es":"Ver el viaje"}'::jsonb);
